class Command(BaseCommand):
    help = "Seed the complete pilot module for Time and Space Complexity."

    def handle(self, *args, **options):
        topic = Topic.objects.filter(slug="time-and-space-complexity").first()
        if topic is None:
            topic = Topic.objects.create(
                title="Time and Space Complexity",
                slug="time-and-space-complexity",
                summary="Analyze algorithm growth and resource use.",
                category="Foundations",
                order=1,
                is_published=True,
            )

        module, _ = LearningModule.objects.update_or_create(
            slug="time-and-space-complexity",
            defaults={
                "title": "Time and Space Complexity",
                "description": "Learn to estimate how an algorithm's work and memory grow with its input.",
                "order": 5,
                "is_published": True,
            },
        )
        lesson_count = 0
        for chapter_order, chapter_data in enumerate(PILOT_CHAPTERS, start=1):
            chapter, _ = LearningChapter.objects.update_or_create(
                module=module,
                slug=slugify(chapter_data["title"]),
                defaults={"title": chapter_data["title"], "order": chapter_order, "is_published": True},
            )
            for lesson_order, data in enumerate(chapter_data["lessons"], start=1):
                content = lesson_content(**{key: data[key] for key in (
                    "introduction", "definition", "theory", "terminology", "concepts", "principle", "steps",
                    "diagram", "example", "code", "lines", "io", "dry", "time", "space", "advantages",
                    "disadvantages", "applications", "mistakes", "interview", "mcq", "practice",
                )})
                expected = {
                    "introduction", "definition", "detailed_theory", "terminology", "core_concepts",
                    "working_principle", "step_by_step", "visual_representation", "real_world_example",
                    "cpp_implementation", "line_by_line_explanation", "input_output_examples", "dry_run",
                    "time_complexity", "space_complexity", "advantages_disadvantages", "real_world_applications",
                    "common_mistakes", "interview_questions", "mcq_quiz", "coding_practice",
                }
                if set(content) != expected or not all(content.values()):
                    raise CommandError(f"Incomplete content schema for lesson: {data['title']}")
                lesson_slug = slugify(data["title"])
                lesson, _ = Lesson.objects.update_or_create(
                    topic=topic,
                    slug=lesson_slug,
                    defaults={
                        "title": data["title"],
                        "introduction": data["introduction"],
                        "explanation": data["theory"],
                        "real_life_example": data["example"],
                        "cpp_code": data["code"],
                        "lesson_content": content,
                        "order": lesson_order,
                        "estimated_minutes": 12,
                        "is_published": True,
                    },
                )
                LearningModuleLesson.objects.update_or_create(
                    module=module,
                    lesson=lesson,
                    defaults={"chapter": chapter, "order": (chapter_order - 1) * 10 + lesson_order},
                )
                lesson_count += 1

        self.stdout.write(self.style.SUCCESS(
            f"Pilot curriculum ready: 1 module, {len(PILOT_CHAPTERS)} chapters, {lesson_count} complete lessons."
        ))
